"use client";
import Link from "next/link";
import { useEffect,useMemo,useState } from "react";
import { ArrowLeft,Edit3,Eye,Plus,Search,Store } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
type Listing={id:string;public_id:string;title:string;item_type:string;price:number|null;currency_code:string|null;status:string;created_at:string};
export default function VendorListingsPage(){const supabase=createClient();const[rows,setRows]=useState<Listing[]>([]);const[q,setQ]=useState("");const[status,setStatus]=useState("all");const[loading,setLoading]=useState(true);const[error,setError]=useState("");async function load(){setLoading(true);setError("");const{data:{user}}=await supabase.auth.getUser();if(!user){window.location.href="/login?next=/vendor/listings";return}let query=supabase.from("marketplace_items").select("id,public_id,title,item_type,price,currency_code,status,created_at").eq("owner_user_id",user.id).order("created_at",{ascending:false});if(status!=="all")query=query.eq("status",status);const{data,error:e}=await query;if(e)setError(e.message);else setRows((data||[])as Listing[]);setLoading(false)}useEffect(()=>{load()},[status]);const shown=useMemo(()=>rows.filter(r=>`${r.public_id} ${r.title} ${r.item_type}`.toLowerCase().includes(q.trim().toLowerCase())),[rows,q]);return <main className="mx-auto max-w-7xl px-4 py-7 sm:px-6 lg:px-8"><Link href="/vendor" className="inline-flex items-center gap-2 text-sm text-[var(--muted)]"><ArrowLeft size={16}/> Vendor Center</Link><div className="mt-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-semibold uppercase tracking-widest text-[var(--muted)]">Vendor Center</p><h1 className="mt-1 text-3xl font-semibold tracking-tight">My listings</h1><p className="mt-2 text-sm text-[var(--muted)]">Create products, services, courses and jobs. New listings remain under review until approved.</p></div><Link href="/vendor/listings/new" className="inline-flex items-center justify-center gap-2 rounded-xl bg-[var(--primary)] px-4 py-3 text-sm font-semibold text-[var(--background)]"><Plus size={17}/> Add listing</Link></div><div className="mt-6 grid gap-3 md:grid-cols-[1fr_auto]"><label className="flex items-center gap-2 rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search title or Listing ID…" className="w-full bg-transparent py-3 text-sm outline-none"/></label><select value={status} onChange={e=>setStatus(e.target.value)} className="rounded-xl border border-[var(--border)] bg-[var(--surface)] px-3 py-3 text-sm"><option value="all">All statuses</option><option value="draft">Draft</option><option value="submitted">Under review</option><option value="approved">Approved</option><option value="published">Published</option><option value="changes_requested">Changes requested</option><option value="rejected">Rejected</option></select></div>{error&&<div className="mt-5 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</div>}<section className="mt-6 overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface)]">{loading?<div className="p-8 text-sm text-[var(--muted)]">Loading listings…</div>:shown.length===0?<div className="p-12 text-center"><Store size={32} className="mx-auto"/><h2 className="mt-4 font-semibold">No listings yet</h2><p className="mt-2 text-sm text-[var(--muted)]">Start by adding your first product, service, course or job.</p><Link href="/vendor/listings/new" className="mt-5 inline-flex items-center gap-2 rounded-xl bg-[var(--primary)] px-4 py-2.5 text-sm font-semibold text-[var(--background)]"><Plus size={16}/> Add listing</Link></div>:<div className="divide-y divide-[var(--border)]">{shown.map(r=><div key={r.id} className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h2 className="font-semibold">{r.title}</h2><span className="rounded-full border border-[var(--border)] px-2.5 py-1 text-[11px] font-semibold">{r.status.replaceAll("_"," ")}</span></div><p className="mt-2 text-xs text-[var(--muted)]">{r.item_type} · {r.public_id} · {r.price==null?"Free/contact":`${r.currency_code||"USD"} ${Number(r.price).toLocaleString()}`}</p></div><div className="flex gap-2"><Link href={`/marketplace/${r.id}`} className="inline-flex items-center gap-2 rounded-xl border border-[var(--border)] px-3 py-2 text-xs font-semibold"><Eye size={14}/> View</Link><Link href={`/vendor/listings/new?edit=${encodeURIComponent(r.id)}`} className="inline-flex items-center gap-2 rounded-xl border border-[var(--border)] px-3 py-2 text-xs font-semibold"><Edit3 size={14}/> Edit</Link></div></div>)}</div>}</section></main>}
